# -*- coding: utf-8 -*-
from pathlib import Path
import json,shutil

ROOT=Path(__file__).resolve().parents[2];W=ROOT/'work/revision-v2';OUT=ROOT/'outputs/带封面-修正版v2'
tech=json.loads((OUT/'技术验证.json').read_text());assert tech['passed'] and tech['checks']['full_video_and_audio_codec_decode']
qas={p:json.loads((W/f'{p}_visual_qa.json').read_text())for p in ['front','middle','late']};assert all(q['status']=='passed'for q in qas.values())
metrics=json.loads((W/'stability_metrics.json').read_text())
rows=[
 ('01:02','保留技能名后缀','遮住地址前缀；保留 /cli、/ai-news-radar。跟随缩放和移动，源确认的顶部裁切单独收边。'),
 ('01:41','收窄 Models.dev','仅遮标签约330px；保留右侧普通中文。'),
 ('01:52','恢复 lark-cli','删除把普通命令名当链接的误框。'),
 ('02:03','恢复“检查AI”','删除该普通文字的误追踪框。'),
 ('06:39','保留 skill 名字','同一 ClawHub 画面按末段技能名裁短，包括相邻技能条目与随后小截图。'),
 ('08:05、08:57','放大文件路径','仅遮 /Users/carl/ 身份前缀，保留 Downloads、后续目录和文件名；移除60帧过高的重复路径框。'),
 ('14:32','遮 .html','只遮当前结果文件的 .html 后缀，保留主体文件名；补到真实切换前的最后一帧。'),
 ('16:12','误码纠正','本地 .hermes/skills/media/local-smart-video-cut 目录和源码标题误当域名；删除本次确认误框及邻帧短闪。'),
 ('25:08、27:17、28:38','放大文件路径','仅遮 /Users/carl/；处理多行、选区、顶部裁切和横向平移，保留目录与文件名。'),
 ('25:38','多行灰条频闪','去掉1361个同URI重复或已确认误框；保留源确认的独立行几何，再稳定静止段。末尾39帧下边补3px，四行之间仍留7px间隙。'),
 ('25:41','待定位 .html','该时间点是天平视频，独立 FFmpeg 取帧已确认；扩查25:00–27:20未找到该后缀。已询问具体画面，未在无关画面加码。'),
 ('32:09–32:53','遮指定词','遮 B站、小红书、中国，包括同屏多次出现及字幕；该范围1321帧逐帧扫描，检测到4260个词框。指定词不采用字幕像素恢复。')]
lines=['# 《带封面》修正版 v2 修改与验证','', '完整版35:29.033，4K、30fps。原片和上一版成片保持不变；原始AAC音轨直接复制。','', '| 用户时间点 | 本次处理 | 结果与边界 |','| --- | --- | --- |']
lines += [f'| {a} | {b} | {c} |'for a,b,c in rows]
lines += ['', '## 灰条如何稳定','', '先合并同目标的重复框，避免OCR框和人工框各自改变边缘。对静止段使用一个覆盖已确认字形的固定矩形；对真正移动的目标保持当前尺度下的尺寸并跟随位置，缩放进入新的尺度段。平滑后的位置受当前帧覆盖约束，不能因为平均而露字。','', '文件路径、扩展名和保留技能后缀的人工窄框有边界保护，不因稳框再次向右扩。没有图像/检测证据的空帧不做盲目延长，切镜或真实出画后撤罩。','', '| 静止取样 | 帧数 | 原版尺寸变化次数 | 修正版尺寸变化次数 |','| --- | ---: | ---: | ---: |']
for v in metrics:lines.append(f'| {v["point"]}附近 | {v["new"]["observed_frames"]} | {v["old"]["size_change_transitions"]} | {v["new"]["size_change_transitions"]} |')
lines += ['', '这些数字只描述所列静止取样段；真实滚动和缩放时仍需要改变位置/尺寸。25:38的主要改善是删除重叠大框、保留四条独立细条。','', '## 验证','', '23项稳框、替换报告、边界、并发和字幕保护相关单元检查通过。实际分段视频按用户点、首尾、缩放转折及确认缺陷复核；指定词范围另完整解码1321帧，检查全部4260个检测词框的实色覆盖。资源尾部5919个源白色笔画像素在成片中均已覆盖。','', '整片技术检查通过：63871帧、连续零起点时间戳、原音轨编码包一致、采样音画同步、修改与拼接处画面校验、全视频和音频完整解码。H264边沿允许少量颜色误差；不会将边沿误差写成文字露出。','', '人工视觉核验仍采用指定场景与困难点抽查，不能宣称全片零漏码。少量网址与字幕或导航重叠的既有取舍保持；25:41的 .html 仍需要用户提供具体画面。','', '文件：[打码汇报](打码汇报.md) · [完整时间轴](时间轴.csv) · [技术验证](技术验证.json) · [审阅页](审阅.html)','']
(OUT/'修订说明.md').write_text('\n'.join(lines),encoding='utf-8')
visual=['# 修正版 v2 视觉检查','', '三组实际视频复验均通过。逐项更正、时间范围、稳框取舍及待定位项见 [修订说明.md](修订说明.md)。','', f'前段：{qas["front"].get("unique_actual_frame_points",38)}个独立实际成片帧点；技能后缀、Models.dev收边、lark-cli和检查AI恢复均通过。缩放过渡修补已单独复验，Microsoft上下行在连续70个静止帧里位置和尺寸固定。','', '中段：按准确PTS取帧复验技能名称、两段身份前缀、.html末帧以及本地源码误码首尾。高重复路径框已去除；相邻ASC技能的末段名字保留。','', '晚段：路径固定点及边界采样保留目录/文件名，身份前缀覆盖。指定词范围完整解码1321帧，对4260个检测词框检查实色覆盖；固定点和30个补洞来源帧OCR复核未发现目标词露出。','', '25:38：重复大框移除，四行窄灰条稳定；尾部39帧原URI下伸的5919个白色笔画像素均已覆盖，指令参数及人像保留。H264条边少量颜色误差按实测容差记录。','', '19:41：实际成片6个滚动/静止取样帧已目视；静止段70帧的目标尺寸变化由20次降为0次。','', '整片帧数、时间戳、音画同步与编码包一致性、源片和上一版保持不变、全部视频/音频解码均通过。','', '人工视觉核验采用用户指定场景和困难点抽查，不能宣称全片零漏码。25:41的.html未定位，已列待澄清；该时刻独立取帧为天平视频，未盲加灰条。','']
(OUT/'视觉检查.md').write_text('\n'.join(visual),encoding='utf-8')
sample=W/'late_masked_samples.jpg'
if sample.exists():shutil.copy2(sample,OUT/'检查样张-路径与指定词.jpg')
print('Revision notes and visual report written')
